Algorithm OrdenarSeis
  Dimension v[6] As Integer;
  For i <- 0 To 5 Do
    Read v[i];
  EndFor
  For i <- 0 To 4 Do
    Define menor As Integer <- i;
    For j <- i + 1 To 5 Do
      If v[j] < v[menor] Then
        menor <- j;
      EndIf
    EndFor
    Define guardado As Integer <- v[i];
    v[i] <- v[menor];
    v[menor] <- guardado;
  EndFor
  For Each n In v Do
    Write n;
  EndFor
EndAlgorithm
